def sortCounterclockwise(points):
    from functools import cmp_to_key

    def half(p):
        return 0 if p[1] > 0 or (p[1] == 0 and p[0] > 0) else 1

    def cmp(a, b):
        ha, hb = half(a), half(b)
        if ha != hb:
            return ha - hb
        cr = a[0] * b[1] - a[1] * b[0]
        if cr > 0:
            return -1
        if cr < 0:
            return 1
        da = a[0] * a[0] + a[1] * a[1]
        db = b[0] * b[0] + b[1] * b[1]
        return (da > db) - (da < db)

    return sorted(points, key=cmp_to_key(cmp))
